import sqlite3
from abc import ABC, abstractmethod
from typing import List, Optional, Any

class Repository(ABC):
    @abstractmethod
    def create(self, entity: Any) -> Any:
        pass

    @abstractmethod
    def get_by_id(self, id: int) -> Optional[Any]:
        pass

    @abstractmethod
    def get_all(self) -> List[Any]:
        pass

    @abstractmethod
    def update(self, entity: Any) -> bool:
        pass

    @abstractmethod
    def delete(self, id: int) -> bool:
        pass

class SQLiteRepository(Repository):
    def __init__(self, db_path: str, table_name: str, create_table_sql: str):
        self.db_path = db_path
        self.table_name = table_name
        self.init_db(create_table_sql)

    def init_db(self, create_table_sql: str):
        with sqlite3.connect(self.db_path) as conn:
            conn.execute(create_table_sql)
            conn.commit()

    def execute_query(self, query: str, params: tuple = ()):
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute(query, params)
            conn.commit()
            return cursor

    def execute_query_fetchall(self, query: str, params: tuple = ()):
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute(query, params)
            return cursor.fetchall()

    def execute_query_fetchone(self, query: str, params: tuple = ()):
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute(query, params)
            return cursor.fetchone()

# Example implementation for a User entity
class User:
    def __init__(self, id: int = None, name: str = "", email: str = ""):
        self.id = id
        self.name = name
        self.email = email

class UserRepository(SQLiteRepository):
    def __init__(self, db_path: str):
        create_table_sql = """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT UNIQUE NOT NULL
        )
        """
        super().__init__(db_path, "users", create_table_sql)

    def create(self, user: User) -> User:
        query = "INSERT INTO users (name, email) VALUES (?, ?)"
        cursor = self.execute_query(query, (user.name, user.email))
        user.id = cursor.lastrowid
        return user

    def get_by_id(self, id: int) -> Optional[User]:
        query = "SELECT id, name, email FROM users WHERE id = ?"
        result = self.execute_query_fetchone(query, (id,))
        if result:
            return User(result[0], result[1], result[2])
        return None

    def get_all(self) -> List[User]:
        query = "SELECT id, name, email FROM users"
        results = self.execute_query_fetchall(query)
        return [User(row[0], row[1], row[2]) for row in results]

    def update(self, user: User) -> bool:
        query = "UPDATE users SET name = ?, email = ? WHERE id = ?"
        cursor = self.execute_query(query, (user.name, user.email, user.id))
        return cursor.rowcount > 0

    def delete(self, id: int) -> bool:
        query = "DELETE FROM users WHERE id = ?"
        cursor = self.execute_query(query, (id,))
        return cursor.rowcount > 0

